insert into public.chapters (id, position, num, title, subtitle, icon)
select id, position, num, title, subtitle, icon from jsonb_populate_recordset(null::public.chapters, $j$[{"id":"overview","position":1,"num":"01","title":"Executive Overview & Philosophy","subtitle":"What GeminiForge V20 is, why it exists, and how the 5 planes fit together","icon":"BookOpen"},{"id":"planes","position":2,"num":"02","title":"5 Planes, 14 Crates & 6-OS Parity","subtitle":"Clear guide to every Rust crate, kernel sandbox boundary, and OS target","icon":"Layers"},{"id":"governor","position":3,"num":"03","title":"Hardware Governor & Computer Use","subtitle":"Split-memory MoE sizing, 4 GB Tier E mode, and the sub-50ms CU router","icon":"Cpu"},{"id":"swarm","position":4,"num":"04","title":"Paperclip Org-Swarm & Junie Lite","subtitle":"Zero-token heartbeats (#3401 fix), atomic 409 checkouts, and two-speed routing","icon":"Network"},{"id":"packs","position":5,"num":"05","title":"25-Pack ForgeHub & Anti-Bloat Diet","subtitle":"On-demand .gfpack catalog and why we pruned 1.4 GB of duplicate dependencies","icon":"Box"},{"id":"prompts","position":6,"num":"06","title":"14 Deep Research Dispatch Prompts","subtitle":"Self-contained specification briefs for sequential 1-by-1 execution","icon":"FileText"},{"id":"patches","position":7,"num":"07","title":"8 Locked Confirms, Spikes & Patches","subtitle":"Accepted architectural decisions (CONFIRM-01–08) and F.1–F.6 drop-in code","icon":"ShieldCheck"}]$j$::jsonb);
